import React, { useEffect, useState } from 'react';
import api from '../services/api';
import { ProjectFinancialSummary, Timesheet } from '../types';
import { ProjectCard } from '../components/ProjectCard';

export function Dashboard() {
  const [projects, setProjects] = useState<ProjectFinancialSummary[]>([]);
  const [timesheets, setTimesheets] = useState<Timesheet[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    fetchData();
  }, []);

  async function fetchData() {
    try {
      setError(null);
      const [projectsData, sheetsData] = await Promise.all([
        api.getAllProjectSummaries(),
        api.getTimesheets(),
      ]);

      setProjects(projectsData);
      setTimesheets(sheetsData);
    } catch (err: any) {
      setError(err.response?.data?.error || 'Failed to load dashboard');
    } finally {
      setLoading(false);
    }
  }

  if (loading) {
    return (
      <div className="flex justify-center items-center h-screen">
        <p className="text-gray-600">Loading dashboard...</p>
      </div>
    );
  }

  const pendingCount = timesheets.filter((t) => t.status === 'pending').length;
  const totalHours = projects.reduce((sum, p) => sum + p.total_hours, 0);
  const totalSpent = projects.reduce((sum, p) => sum + p.total_spent, 0);

  return (
    <div>
      {error && (
        <div className="mb-6 p-4 bg-red-50 border border-red-200 rounded-lg text-red-700">
          {error}
        </div>
      )}

      {/* Quick Stats */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
        <div className="bg-white p-6 rounded-lg shadow">
          <p className="text-gray-600 mb-2">Pending Approvals</p>
          <p className="text-3xl font-bold text-blue-600">{pendingCount}</p>
        </div>
        <div className="bg-white p-6 rounded-lg shadow">
          <p className="text-gray-600 mb-2">Total Hours</p>
          <p className="text-3xl font-bold text-green-600">{totalHours.toFixed(1)}</p>
        </div>
        <div className="bg-white p-6 rounded-lg shadow">
          <p className="text-gray-600 mb-2">Total Spent</p>
          <p className="text-3xl font-bold text-purple-600">${totalSpent.toLocaleString()}</p>
        </div>
        <div className="bg-white p-6 rounded-lg shadow">
          <p className="text-gray-600 mb-2">Projects</p>
          <p className="text-3xl font-bold text-orange-600">{projects.length}</p>
        </div>
      </div>

      {/* Project Cards */}
      <h2 className="text-2xl font-bold text-gray-900 mb-6">Active Projects</h2>
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {projects.map((project) => (
          <ProjectCard key={project.id} project={project} />
        ))}
      </div>

      {projects.length === 0 && (
        <div className="text-center py-12 bg-white rounded-lg">
          <p className="text-gray-600">No active projects</p>
        </div>
      )}
    </div>
  );
}
